var DATA = {"domain": "1D heat rod", "boundary": "x=0 wall", "type": "Dirichlet", "form": "T(0) = 300 K", "n": "11"};
var N = parseInt(DATA.n, 10) || 11;
var u = [];
for (var i = 0; i < N; i++) u.push(0);
// interior initial guess: linear ramp
for (var j = 1; j < N - 1; j++) u[j] = j / (N - 1);
console.log("Domain: " + DATA.domain + " | Boundary: " + DATA.boundary);
console.log("Condition: " + DATA.type + " — " + DATA.form);
// apply Dirichlet ends: u(0)=0, u(1)=1 ; Neumann would fix the slope instead
u[0] = 0; u[N - 1] = 1;
// a few Jacobi relaxations of Laplace's equation on the interior
for (var it = 0; it < 50; it++) {
  var v = u.slice();
  for (var k = 1; k < N - 1; k++) v[k] = 0.5 * (u[k - 1] + u[k + 1]);
  u = v;
  u[0] = 0; u[N - 1] = 1; // re-apply boundary condition
}
console.log("Solution after 50 relaxations (N=" + N + "):");
console.log("  " + u.map(function (x) { return x.toFixed(3); }).join(" "));
console.log("RESULT: boundary condition '" + DATA.type + "' applied and interior relaxed.");

